      const { logFallback } = await import('../providers/channel-dispatcher');
      expect(() => logFallback('email', 'skipped', 'not_configured')).not.toThrow();
    });

    it('logs error status with reason', async () => {
      const { logFallback } = await import('../providers/channel-dispatcher');
